"""Generate a plain-language companion to the detailed audit report."""
import pathlib,json,csv,html,datetime,collections,platform,sys
from zoneinfo import ZoneInfo
ROOT=pathlib.Path(__file__).resolve().parent
names={'qwen15-q4':'Current Qwen 1.5B','qwen05-q4':'Qwen 0.5B · compact','qwen05-q8':'Qwen 0.5B · higher precision','qwen3-06-q8':'Qwen3 0.6B','t5-tiny':'Tiny T5 grammar model','rules':'Built-in rules only','qwen15-ct2':'Current Qwen 1.5B · CT2 format','qwen25-3-ct2':'Qwen 3B upper reference · CT2 format'}
def read_csv(name):
 p=ROOT/name
 return list(csv.DictReader(p.open())) if p.exists() else []
def main():
 fmt=read_csv('results/format_summary.csv');speed=read_csv('results/speed_summary.csv');asr=read_csv('results/asr_summary.csv');selected=[x for x in fmt if x['mode']=='shipped' and float(x['budget'])==600]
 current_machine=platform.node().split('.')[0];primary_tier='t3' if sys.platform=='darwin' else 't1' if any(r['machine']==current_machine and r['tier']=='t1' for r in fmt) else 't2'
 fmt=[r for r in fmt if r['machine']==current_machine and r['tier']==primary_tier];speed=[r for r in speed if r['machine']==current_machine and r['tier']==primary_tier];asr=[r for r in asr if r['machine']==current_machine and r['tier']==primary_tier];selected=[r for r in fmt if r['mode']=='shipped' and float(r['budget'])==600]
 latest_speeds={}
 for r in speed:
  if r['mode']=='shipped' and r['input']=='60_words':
   key=r['model']
   rank=lambda x:{'v1-exploratory':0,'speed-v2-natural-prose':1,'speed-v3-diagnostic-repeat':2}.get(x.get('protocol'),0)
   if key not in latest_speeds or rank(r)>=rank(latest_speeds[key]):latest_speeds[key]=r
 weights={'qwen15-q4':1117320736,'qwen05-q4':491400032,'qwen05-q8':675710816,'qwen3-06-q8':639446688,'t5-tiny':32414206,'rules':0}
 for model,folder in [('qwen15-ct2','jncraton--Qwen2.5-1.5B-Instruct-ct2-int8'),('qwen25-3-ct2','qwen25-3-ct2-converted')]:
  file=ROOT/'models'/folder/'model.bin'
  if file.exists():weights[model]=file.stat().st_size
 out=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FlowState · Results explained</title><style>body{max-width:1080px;margin:45px auto;padding:0 24px;font:17px/1.65 -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;color:#172033;background:#f7f8fc}h1{font-size:38px;line-height:1.15;letter-spacing:-1px}h2{margin-top:35px;font-size:25px}.kicker{color:#315fc4;font-size:13px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase}.note{background:#fff;padding:24px;border-radius:14px}table{border-collapse:collapse;width:100%;font-size:15px;background:#fff}td,th{text-align:left;padding:15px;border-bottom:1px solid #dfe5ef}th{background:#eaf0fb}.scroll{overflow-x:auto}small,.muted{color:#52617a}a{color:#235bd1}li{margin:10px 0}.pill{display:inline-block;padding:4px 10px;background:#e7edf8;border-radius:20px;font-size:13px}details{margin-top:25px}pre{white-space:pre-wrap;font:15px/1.6 system-ui;background:white;padding:20px}footer{margin:40px 0;font-size:13px;color:#52617a}</style><div class="kicker">FlowState model benchmark</div><h1>Which smaller models earn their place?</h1><p class="pill">Interim Mac results · Windows and your voice still needed</p><div class="note"><b>Recommendation for now: keep the current defaults.</b><p>A smaller download is useful only if it keeps your words, formats them properly, and is at least as quick on the same device. The first smaller Qwen2.5 models save space and usually finish short text faster, but their layout results do not meet the current formatter on this test set. The smaller quick screen provides directional guidance; it is not a comprehensive certification.</p></div>','<h2>Full formatting comparison · 300 text examples</h2>', '<p>This is your Apple M2 Max Mac with 32 GB of memory. The formatting comparison uses the processor, with six threads. Apple-native speech models are separate tests. Nothing here is a timing estimate for your Windows graphics card.</p>','<div class="scroll"><table><thead><tr><th>Formatter</th><th>Model weights</th><th>Typical 60-word wait</th><th>Slower-case wait</th><th>Layout checks passed</th></tr></thead><tbody>']
 for r in selected:
  model=r['model'];s=latest_speeds.get(model);layout=float(r['layout_proxy'])*100 if r['layout_proxy'] else None
  out.append('<tr><td>'+html.escape(names.get(model,model))+'</td><td>'+('No model download' if model=='rules' else f'{weights[model]/1e6:,.0f} MB' if model in weights else 'Not recorded')+'</td><td>'+(f"{float(s['median_s']):.2f} seconds" if s else 'Not measured yet')+'</td><td>'+(f"{float(s['p95_s']):.2f} seconds" if s else 'Not measured yet')+'</td><td>'+(f'{layout:.1f}%' if layout is not None else 'Not measured')+'</td></tr>')
 out+=['</tbody></table></div><p class="muted"><small>“Typical” is the median of repeated timed calls; “slower-case” is the 95th percentile, so an occasional stall matters. The layout percentage is a strict structural check on deliberately difficult text examples, not the app’s overall speech accuracy. Some alternative layouts are valid. The detailed report contains confidence intervals, raw outputs and limitations. Weight sizes exclude software and small support files.</small></p>', '<h2>The three things the benchmark checks</h2><ul><li><b>Recognition:</b> did the app hear the right words, including technical names, quiet speech and long recordings?</li><li><b>Formatting:</b> did it preserve those words while arranging emails, lists, paragraphs, capitals and punctuation?</li><li><b>Speed:</b> how long do you wait for a live chunk and after stopping, including slower runs and memory pressure?</li></ul>', '<h2>How I ran the formatting tests</h2><ol><li>Checked your actual FlowState code. It is version 1.0.7-beta; the pasted brief described an earlier version. The main settings match.</li><li>Created a separate benchmark folder and software environment. The original FlowState source has passed an integrity check and remains unchanged.</li><li>Wrote 150 examples across 15 categories, each with two input styles: a 300-case pool. The full 300-row text set has been restored after review, with forced-AI and per-category diagnostics. The app’s own teaching examples are kept out of the score.</li><li>Ran FlowState’s real cleanup process, including its word-preservation safeguard. Saved both the model response and the final text.</li><li>Tested its normal CPU behavior and a mode that lifts the length limit. Used the real time limits and a generous limit to separate quality from speed. Repeated the tests to check consistency.</li><li>Ran separate speed trials after warm-up. Older exploratory long-text timings are retained and identified; the revised long input uses natural prose so a model cannot look fast merely by rejecting repetitive text.</li></ol>', '<h2>An important failure the averages could hide</h2><p>Some formatter models answer a dictated request instead of formatting the words. For example, they write a poem when the input says “write me a poem about cats.” This happens with the current formatter as well as smaller versions.</p><p>In the examples reviewed, FlowState’s safeguard caught those answers and restored the dictated words. The report shows that as a caught model failure, not a successful formatting response. The safeguard must stay in place.</p>', '<h2>Speech models, including the small Parakeet versions</h2><p>The downloaded shortlist includes the existing Whisper models, compressed Parakeet v2/v3 for portable use, the approximately 500 MB Apple-native Parakeet path used by BetterVoice, smaller native precision variants, and the approximately 220 MB Redux model. Redux is a separately trained model and must pass its own accuracy checks. A successful download is not counted as a successful test.</p>']
 paired=[r for r in read_csv('results/format_paired_invoked.csv') if r['machine']==current_machine and r['tier']==primary_tier]
 out+=['<h2>Fairer comparison: only when the AI actually ran</h2><p>The headline formatting table includes the whole app pipeline. The table below removes cases that never reached AI and compares each candidate with the current formatter on identical inputs. Scores refer only to the email, list and paragraph examples where the layout check applies. They are strict automated checks, not a human rating of all dictation.</p><div class="scroll"><table><tr><th>Candidate</th><th>Same inputs reaching both AIs</th><th>Current formatter layout</th><th>Candidate layout</th></tr>']
 for r in paired:
  if r['mode']=='shipped':out.append('<tr><td>'+html.escape(names.get(r['model'],r['model']))+'</td><td>'+r['matched_invoked']+' total; '+r['layout_pairs']+' layout cases</td><td>'+html.escape(r['baseline_layout'])+'%</td><td>'+html.escape(r['candidate_layout'])+'%</td></tr>')
 out+=['</table></div><p><small>Brackets show the uncertainty interval. The smaller Qwen 0.5B versions remain behind the current model on this synthetic layout set. This strengthens the reason to keep the default; it does not settle speech accuracy or Windows speed.</small></p><h2>Corrections after an outside review</h2><p>The detailed report now separates AI-used cases, fixes the failure-example headings, removes repeated input examples, and adds a spacing-neutral character score. Exact match already ignored blank lines. Earlier long-input speed figures came from different inputs; occasional slow calls remain visible and are being rechecked. A confirmed FlowState rule removes a meaningful word from “twenty twenty six” before AI sees it. The app itself has not been changed.</p>']
 if asr:
  out+=['<div class="scroll"><table><tr><th>Speech model</th><th>Test set</th><th>Clips scored</th><th>Word errors</th></tr>']
  for r in asr:
   if r['subset'] in ['test-clean','test-other']:out.append(f"<tr><td>{html.escape(r['model'])}</td><td>{html.escape(r['subset'])}</td><td>{r['count']}</td><td>{100*float(r['wer']):.2f}%</td></tr>")
  out.append('</table></div>')
 else:out.append('<p><b>Scored speech results are still pending.</b> The report will not invent accuracy figures from model descriptions or downloads.</p>')
 out+=['<h2>What is still needed for a final verdict</h2><ul><li>The shortened public speech run and three representative long-recording checks on this Mac.</li><li>Your 25 recordings, with the written references checked against what you actually said.</li><li>The corresponding Windows GPU and CPU runs. Results from the two machines will stay separate.</li><li>A blind human review of output pairs. The earlier automated judge is excluded; only entered human grades count.</li><li>Reference word timings for reliable boundary-error and minute-by-minute checks. Simulated stop timing is not a live paste-speed measurement.</li></ul>', '<p>Until these are available, no model is certified as a replacement. Android performance and low-end graphics-card memory fit have not been measured on this Mac.</p>', '<h2>Read and review the evidence</h2><p><a href="REPORT.html">Detailed report: methods, tables, uncertainty and failure examples</a></p><p><a href="RECORDING_SHEET.html">Your recording sheet</a></p><p><a href="HUMAN_REVIEW.csv">Blind human review sheet</a></p>', '<footer>Updated '+datetime.datetime.now(ZoneInfo('Asia/Kolkata')).strftime('%d %B %Y at %I:%M %p IST')+'. All inference and recordings stay local. The software and model versions are recorded in the benchmark folder.</footer></html>']
 expected={'whisper-base','whisper-small','whisper-turbo','parakeet-v2-int8','parakeet-v3-int8','parakeet-coreml-v2','parakeet-coreml-v3','parakeet-coreml-v3-int4','parakeet-coreml-v3-int8v2','parakeet-coreml-redux'}
 macdone=expected<={r['model'] for r in asr} and any((ROOT/'results').glob('*/*-quick-decision/FINISHED.json')) and any(r['model']=='whisper-base' and r['input']=='14-second speech' for r in speed)
 if macdone:
  out=[x.replace('The first smaller Qwen2.5 models save space and usually finish short text faster, but their layout results do not meet the current formatter on this test set.','Only completed local conditions appear in this page. Use the measured tables and entered human review before changing defaults.').replace('Interim Mac results · Windows and your voice still needed','Quick Mac comparison complete · Windows and your voice still separate').replace('<li>The shortened public speech run and three representative long-recording checks on this Mac.</li>','').replace('The earlier 8-second small-model outlier did not recur','The earlier 8-second small-model outlier did not recur') for x in out]
 review2=ROOT/'review2_status.json'
 if review2.exists():
  st=json.loads(review2.read_text());label='Review corrections running' if st['state']=='running' else 'Review Mac checks ended; Windows GPU still separate'
  out=[x.replace('Quick Mac comparison complete · Windows and your voice still separate',label).replace('Interim Mac results · Windows and your voice still needed',label) for x in out]
  out.append('<p><b>Current review status:</b> '+html.escape(st['phase'])+'. The earlier portable streaming wiring was faulty; its old fallback results are withdrawn pending corrected runs. The real RTX GPU comparison remains a Windows task.</p>')
 if sys.platform!='darwin':
  description='This page shows the Windows '+('NVIDIA GPU' if primary_tier=='t1' else 'CPU-only')+' condition. The detailed report records the actual hardware, runtime and package versions. Apple-native speech results require separate Mac runs.'
  out=[x.replace('The first smaller Qwen2.5 models save space and usually finish short text faster, but their layout results do not meet the current formatter on this test set.','Only completed local conditions appear in this page. Use the measured tables and entered human review before changing defaults.').replace('Interim Mac results · Windows and your voice still needed','Windows measurements · voice and human review separate').replace('This is your Apple M2 Max Mac with 32 GB of memory. The formatting comparison uses the processor, with six threads. Apple-native speech models are separate tests. Nothing here is a timing estimate for your Windows graphics card.',description).replace('The downloaded shortlist includes the existing Whisper models, compressed Parakeet v2/v3 for portable use, the approximately 500 MB Apple-native Parakeet path used by BetterVoice, smaller native precision variants, and the approximately 220 MB Redux model. Redux is a separately trained model and must pass its own accuracy checks. A successful download is not counted as a successful test.','Windows tests use the selected portable backends. Apple-native Parakeet is a separate Mac condition. Only completed local runs count as measurements.') for x in out]
 (ROOT/'RESULTS_EXPLAINED.html').write_text('\n'.join(out));print('Plain-language results page updated')
if __name__=='__main__':main()
